cils.css:
.card {
  text-align: center;
  font-size: 17px;
  line-height: 1.6;
}
.uc-ask {
  margin-bottom: 14px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
}
.uc-word {
  font-size: 38px;
  font-weight: 400;
  line-height: 1.2;
}
/* THE ARTICLE IS COLOURED BY THE GENDER IT MARKS, which is the one thing `l'`
   cannot say on its own -- `l'amico` and `l'amica` are spelled alike.  The
   plural on the line below says it too (`gli amici` against `le amiche`); this
   says it at a glance.  Two colours only: Italian has no neuter. */
.uc-art {
  font-weight: 500;
}
.uc-m {
  color: var(--indigo, #3D4E8F);
}
.uc-f {
  color: var(--zh, #C8453C);
}
.uc-say {
  margin-left: 14px;
  vertical-align: middle;
  font-size: 15px;
}
.uc-field {
  display: block;
  width: fit-content;
  /* A FLOOR, because Italian's commonest words gloss in one word.  The box hugs
     its contents, and on `io` -> `I` that leaves a narrow stamp adrift in the
     middle of a 680px card under a rule spanning the whole of it, which reads
     as a fault rather than a design.  min() so a narrow phone still gets the
     full width. */
  min-width: min(300px, 100%);
  max-width: 100%;
  margin: 14px auto 0;
  padding: 11px 15px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  text-align: left;
  background: color-mix(in srgb, var(--paper-2, #EFEDE6) 58%, var(--card, #FFFFFF));
}
.uc-pos {
  margin-bottom: 3px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint, #6C6A63);
}
.uc-gl {
  line-height: 1.5;
}
.uc-gls {
  margin: 0;
  padding-left: 0;
  list-style: none;
  line-height: 1.5;
}
.uc-forms {
  margin-top: 8px;
  font-size: 15px;
}
.uc-fi + .uc-fi {
  margin-left: 14px;
}
.uc-fl {
  margin-right: 6px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-fold {
  margin-top: 14px;
  text-align: left;
}
.uc-fold > summary {
  cursor: pointer;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.6;
}
.uc-conj {
  margin-top: 10px;
}
/* THE PARADIGM IS A GRID OF BLOCKS, not one long column.  An Italian verb has
   seven tenses of six persons each, which stacked is a card six screens tall;
   two-up it is two.  `minmax(0,1fr)` because a cell holding `avremmo parlato`
   would otherwise claim its own intrinsic width and push the grid wider than
   the card. */
.uc-cjg {
  display: grid;
  gap: 12px 18px;
  grid-template-columns: repeat(auto-fit, minmax(min(210px, 100%), 1fr));
}
.uc-cj {
  min-width: 0;
}
.uc-cjh {
  padding-bottom: 3px;
  border-bottom: 1px solid var(--rule, rgba(0,0,0,0.10));
  font-size: 9.5px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-cjr {
  display: flex;
  gap: 10px;
  align-items: baseline;
  padding: 1.5px 0;
  font-size: 14px;
}
.uc-cj-p {
  flex: 0 0 auto;
  opacity: 0.55;
}
.uc-cj-f {
  flex: 1 1 auto;
  text-align: right;
  font-weight: 500;
}
.uc-exs {
  margin-top: 10px;
}
.uc-exi {
  padding: 9px 0;
  text-align: center;
}
.uc-exi + .uc-exi {
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
}
.uc-exz {
  font-size: 16px;
  line-height: 1.55;
}
.uc-exz b {
  font-weight: 600;
  color: var(--zh, #C8453C);
}
.uc-exe {
  margin-top: 3px;
  font-size: 13px;
  opacity: 0.62;
}
.uc-exsay {
  margin-right: 7px;
}
.uc-cj-e{font-weight:700;color:var(--zh, #C8453C);}

/* A GENDERED NOUN'S PARADIGM IS A GRID, its columns the genders and its rows the numbers.
   Divs rather than a table: `SANITIZE_TAGS` has no `table`/`tr`/`td` and unwraps what it does
   not know, so a real table would arrive as one run-on line.  See `.claude/gender-tables.py`. */
.uc-gt {
  display: grid;
  gap: 3px 14px;
  margin-top: 8px;
  font-size: 15px;
  align-items: baseline;
  grid-template-columns: auto minmax(0, 1fr) minmax(0, 1fr);
}
.uc-gt.uc-gt2 {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}
.uc-gth,
.uc-gtl {
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-gtl {
  padding-right: 2px;
}
.uc-gtx {
  opacity: 0.35;
}
